// generated by build.sh: every image's size in bytes, the game script's, then src/05_loader.js
var IMG_BYTES = {'ball_0.webp':6928,'ball_1.webp':6980,'ball_2.webp':7042,'ball_3.webp':7162,'ball_4.webp':6950,'ball_5.webp':7074,'ball_6.webp':6714,'ball_7.webp':7202,'bg_foreL.webp':40856,'bg_foreR.webp':36360,'bg_ground.webp':160044,'bg_lake.webp':72082,'bg_mount.webp':102332,'bg_trees.webp':155612,'cage_x.webp':25006,'cannon1.webp':41744,'cannon1_front.webp':7812,'cannon2.webp':48614,'cannon2_front.webp':13112,'cloud.webp':25938,'fire.webp':13708,'pause.webp':7326,'play.webp':7204,'playbtn.webp':28192,'rack.webp':33790,'rack_front.webp':19772,'sound.webp':8086,'t_cage.webp':25006,'t_cannon.webp':91678,'t_fire.webp':14782,'t_logo.webp':152822,'xchar.webp':7980,};
var LOAD_SCRIPT = ['js/script.js', 360510];
// =====================================================================
//  LOADER: the start screen while the game loads. It runs before the game script (it is what loads it)
//  and needs only GSAP. build.sh puts IMG_BYTES (every image's size) and LOAD_SCRIPT above it.
//  • A horizontal bar fills where the Play button will appear (TL.play), by bytes: first the page
//    (its images, the font, the game script), then the images the game asks for (Loader.load).
//    Smoothed, never backwards, never faster than MIN_FILL (a cached load still reads as a bar
//    filling), and it keeps creeping while a big file is on its way, so it never looks stuck.
//  • The painted scene fades in behind it as soon as the game has laid it out (Loader.scene) and
//    its pictures have arrived.
//  • Loader.finish() (the game is ready): the bar fills, flashes and collapses, and hands its place
//    to the Play button (Title.start pops it in right there).
//  Transform + opacity only, time-based (gsap.ticker). Reduced motion: no smoothing, stripes or flash.
//  The stage is fitted to the screen before the first paint by fitStage() (inline in index.html).
// =====================================================================
var Loader = (function () {
  'use strict';
  var MIN_FILL = 1.2;                  // s: the shortest fill
  var CAP = 12;                        // s: a file that never answers stops holding the game up after this
  var FONT_BYTES = 40000, OTHER_BYTES = 30000; // about what the Fredoka faces weigh; a file not in IMG_BYTES
  var PAGE = 0.45;                     // the bar's share for the page; the rest is the game's own images
  var $ = function (s) { return document.querySelector(s); };
  var delay = function (s) { return new Promise(function (r) { setTimeout(r, s * 1000); }); }; // (waiting on the network, not motion)
  var reduced = false;
  try { reduced = matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* old browser */ }
  var d = function (s) { return reduced ? 0 : s; };

  var bar = $('#loadBar'), clip = bar.querySelector('.lbClip'), fill = bar.querySelector('.lbFill'), stripes = bar.querySelector('.lbStripes'),
    head = bar.querySelector('.lbBall'), glint = bar.querySelector('.lbFlash'), label = $('#loadText'), pctEl = label.querySelector('.lbPct');
  // the ball at the bar's tip rolls from one rounded end to the other; the fill's edge stays under it
  var R = clip.offsetHeight / 2, HEAD0 = clip.offsetLeft + R, TRAVEL = clip.offsetWidth - 2 * R;

  // ---- what is loading: two pools of bytes, each { done, total } ----
  var page = { done: 0, total: 0 }, game = null, seen = {};
  var bytesOf = function (url) { return IMG_BYTES[decodeURIComponent(url.split('?')[0].split('/').pop())] || OTHER_BYTES; };
  function count(pool, bytes, p) { pool.total += bytes; return p.then(function () { pool.done += bytes; }); }
  function imgDone(im) { // resolves when the picture has arrived (or failed: the game carries on without it)
    return new Promise(function (res) {
      if (im.complete) { res(); return; }
      im.addEventListener('load', res, { once: true }); im.addEventListener('error', res, { once: true });
    });
  }
  // the page's own pictures (the scene, the sprites, the buttons) are already on their way
  Array.prototype.forEach.call(document.images, function (im) {
    if (!im.src || seen[im.src]) return;
    seen[im.src] = imgDone(im);
    count(page, bytesOf(im.src), seen[im.src]);
  });
  var font = document.fonts && document.fonts.load ? document.fonts.load('700 64px Fredoka').catch(function () {}) : Promise.resolve();
  count(page, FONT_BYTES, font);
  page.total += LOAD_SCRIPT[1];        // (counted when it has run: loadScript)

  // ---- the painted scene fades in once the game has laid it out and its pictures are here (decoded: no hitch) ----
  var world = $('#world'), bg = $('#bg'), laidOut, sceneIn = new Promise(function (r) { laidOut = r; });
  var bgImgs = bg ? (bg.tagName === 'IMG' ? [bg] : Array.prototype.slice.call(bg.querySelectorAll('img'))) : [];
  Promise.race([Promise.all([sceneIn].concat(bgImgs.map(function (im) {
    return imgDone(im).then(function () { return im.decode ? im.decode().catch(function () {}) : 0; });
  }))), delay(CAP)]).then(function () { gsap.to(world, { opacity: 1, duration: d(0.5), ease: 'power2.out' }); });

  var shown = 0, drawn = -1, age = 0, creep = 0, lastPct = -1;
  var ready = false, finished = false, hasWords = false, takeover = null, loops = [];

  // ---- the bar ----
  head.style.willChange = 'transform';
  if (!reduced) {
    stripes.style.willChange = 'transform';
    loops.push(gsap.to(stripes, { x: 48, duration: 0.7, ease: 'none', repeat: -1 })); // one stripe period: a seamless loop
  }
  gsap.set(label, { y: 8 });
  function words() { // the words have arrived (I18n): show the label once its font is in (or after a moment)
    hasWords = true; render(true);
    Promise.race([font, delay(1.2)]).then(function () {
      if (!finished) gsap.to(label, { opacity: 1, y: 0, duration: d(0.3), ease: 'power2.out' });
    });
  }
  function render(force) {
    if (shown !== drawn) {
      drawn = shown;
      fill.style.transform = 'translateX(' + ((shown - 1) * 100).toFixed(3) + '%)';
      head.style.transform = 'translateX(' + (HEAD0 + shown * TRAVEL).toFixed(2) + 'px)';
    }
    var pct = Math.floor(shown * 100 + 1e-6);
    if (pct !== lastPct || force) {
      lastPct = pct; bar.setAttribute('aria-valuenow', pct);
      if (hasWords) pctEl.textContent = T('loadingPct', { pct: pct });
    }
  }
  function tick(time, deltaMs) {
    var dt = Math.min(0.05, Math.max(0, deltaMs / 1000)), goal;
    age += dt;
    var real = PAGE * Math.min(1, page.done / page.total) + (game && game.total ? (1 - PAGE) * Math.min(1, game.done / game.total) : 0);
    if (ready) goal = 1;
    else { creep += dt * 0.06 * (1 - creep); goal = Math.min(0.95, real + (1 - real) * 0.5 * creep); } // while waiting, it creeps on
    if (reduced) shown = Math.max(shown, goal);
    else {
      var k = Math.min(1, age / MIN_FILL), g = Math.min(goal, 1 - (1 - k) * (1 - k)); // never faster than an ease-out over MIN_FILL
      if (g > shown) {
        var rate = ready ? 12 : 5, minSpeed = ready ? 1.2 : 0;
        shown = Math.min(g, shown + Math.max((g - shown) * (1 - Math.exp(-dt * rate)), minSpeed * dt));
      }
    }
    render();
    if (ready && shown >= 1 && !finished) complete();
  }
  gsap.ticker.add(tick);

  // ---- done: flash, collapse, and hand the spot to the Play button ----
  function complete() {
    finished = true;
    gsap.ticker.remove(tick);
    if (reduced) { gsap.set([bar, label], { opacity: 0 }); takeover(); cleanup(); return; }
    bar.style.willChange = 'transform,opacity';
    gsap.timeline({ onComplete: cleanup })
      .to(glint, { opacity: 1, duration: 0.12, ease: 'power2.out' }, 0)
      .to(glint, { opacity: 0, duration: 0.3, ease: 'power2.in' }, 0.12)
      .to(bar, { scale: 1.05, duration: 0.14, ease: 'power2.out' }, 0)
      .to(bar, { scale: 1, duration: 0.18, ease: 'power2.inOut' }, 0.14)
      .to(label, { opacity: 0, y: 10, duration: 0.2, ease: 'power2.in' }, 0.2)
      .call(function () { takeover(); }, null, 0.34)
      .to(bar, { scaleX: 0.2, scaleY: 0.5, opacity: 0, duration: 0.28, ease: 'back.in(1.6)' }, 0.34);
  }
  function cleanup() { // the loading screen unmounts: no loops, no listeners, no elements left
    loops.forEach(function (tw) { tw.kill(); }); loops = [];
    gsap.killTweensOf([bar, label, glint, stripes]);
    bar.remove(); label.remove();
  }

  return {
    words: words,
    loadScript: function (src) {       // the game itself (index.html calls this once the words are in)
      var s = document.createElement('script');
      s.src = src;
      s.onload = s.onerror = function () { page.done += LOAD_SCRIPT[1]; };
      document.body.appendChild(s);
    },
    scene: function () { laidOut(); }, // the game has laid out the stage and its camera: the scene can show
    load: function (names, dir) {      // the images the game needs (+ the font); resolves when all are in, or after CAP
      game = { done: 0, total: 0 };
      var jobs = names.map(function (n) {
        var im = new Image(); im.src = (dir || 'assets/img/') + n;
        var p = seen[im.src] || (seen[im.src] = imgDone(im));
        return count(game, bytesOf(im.src), p);
      });
      return Promise.race([Promise.all(jobs.concat([font])), delay(CAP)]);
    },
    finish: function () {              // the game is ready; resolves as the bar collapses, when the Play button should pop in
      removeEventListener('resize', fitStage); // (the game's Stage keeps the screen fitted from here)
      ready = true;
      return new Promise(function (res) { takeover = res; });
    },
  };
})();
